 "content": "from collections import deque

def comps(grid, color):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=color or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          x,y=q.pop(); cells.append((x,y))
          for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            a,b=p
            if 0<=a<h and 0<=b<w and grid[a][b]==color and p not in seen: seen.add(p);q.append(p)
        out.append(cells)
    return out

def norm(cells):
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    return frozenset((r-mr,c-mc) for r,c in cells)

def transform(grid):
    out=[row[:] for row in grid]
    templates={}
    for color in range(2,10):
      for cells in comps(grid,color):
        templates.setdefault(norm(cells), color)
    for cells in comps(grid,1):
      color=templates.get(norm(cells))
      if color is not None:
        for r,c in cells: out[r][c]=color
    return out
